require dirname(__DIR__, 2).'/inc/config.php';require dirname(__DIR__, 2).'/inc/nen-tang.php';$nd=yeuCauQuyen('quan_tri');$uid=(int)$nd['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=idDuong($_POST['id']??null);$loai=layChuoi($_POST,'loai');$hd=layChuoi($_POST,'hanh_dong');
 if(!$id || !in_array($hd,['duyet','tu_choi'],true) || !in_array($loai,['nguoi_ban','tin_dang'],true)) saiDuLieu('Thao tác không hợp lệ.');
 if($loai==='nguoi_ban'){$s=db()->prepare("UPDATE ho_so_nguoi_ban SET trang_thai=? WHERE nguoi_dung_id=? AND trang_thai='cho_duyet'");$s->execute([$hd==='duyet'?'da_duyet':'tu_choi',$id]);}
 else{
  $db=db();$db->beginTransaction();try{
   $s=$db->prepare("SELECT t.* FROM tin_dang_ngoc t JOIN ho_so_nguoi_ban h ON h.nguoi_dung_id=t.nguoi_ban_id AND h.trang_thai='da_duyet' WHERE t.id=? AND t.trang_thai='cho_duyet' FOR UPDATE");$s->execute([$id]);$t=$s->fetch();if(!$t) saiDuLieu('Tin đăng không còn trong trạng thái chờ.');
   if($hd==='duyet'){
    // Phê duyệt hồ sơ không phải chứng nhận chất lượng viên ngọc.
    $ma='SELL-'.$id;$s=$db->prepare("INSERT INTO san_pham(danh_muc_id,ma,ten,loai,gia,ton_kho,xuat_xu,kiem_dinh,anh,anh_chung_thu,mo_ta) VALUES(?, ?, ?, 'Ngọc do người bán cung cấp', ?, ?, ?, 'Chứng thư do người bán cung cấp', ?, ?, ?)");$s->execute([$t['danh_muc_id'],$ma,$t['ten'],$t['gia'],$t['ton_kho'],$t['xuat_xu'],$t['anh'],$t['anh_chung_thu'],$t['mo_ta']]);$sanPhamId=(int)$db->lastInsertId();$db->prepare('UPDATE san_pham SET nguoi_ban_id=? WHERE id=?')->execute([$t['nguoi_ban_id'],$sanPhamId]);$db->prepare("UPDATE tin_dang_ngoc SET trang_thai='da_duyet',san_pham_id=? WHERE id=?")->execute([$sanPhamId,$id]);$db->prepare("UPDATE kiem_dinh_ngoc SET trang_thai='tai_lieu_hop_le',nguoi_duyet_id=?,ngay_duyet=NOW(),ghi_chu='Đã kiểm tra sự hiện diện của tài liệu; chưa xác minh độc lập' WHERE tin_dang_id=?")->execute([$uid,$id]);
   }else{$db->prepare("UPDATE tin_dang_ngoc SET trang_thai='tu_choi' WHERE id=?")->execute([$id]);$db->prepare("UPDATE kiem_dinh_ngoc SET trang_thai='can_bo_sung',nguoi_duyet_id=?,ngay_duyet=NOW(),ghi_chu='Cần bổ sung hoặc chỉnh sửa hồ sơ' WHERE tin_dang_id=?")->execute([$uid,$id]);}
   $db->commit();
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
 }
 chuyenTrang('kiem-duyet.php','Đã cập nhật hồ sơ kiểm duyệt.');
}
$ban=db()->query("SELECT h.*,nd.ho_ten FROM ho_so_nguoi_ban h JOIN nguoi_dung nd ON nd.id=h.nguoi_dung_id WHERE h.trang_thai='cho_duyet' ORDER BY h.ngay_dang_ky")->fetchAll();$tin=db()->query("SELECT t.*,nd.ho_ten FROM tin_dang_ngoc t JOIN nguoi_dung nd ON nd.id=t.nguoi_ban_id WHERE t.trang_thai='cho_duyet' ORDER BY t.ngay_tao")->fetchAll();$tieuDe='Kiểm duyệt JadeHub';require dirname(__DIR__, 2).'/inc/header.php';?>
<main id="noi-dung" class="jh-page"><h1>Kiểm duyệt người bán và chứng thư</h1><?php require dirname(__DIR__, 2).'/inc/thong-bao.php';?><h2>Người bán chờ duyệt</h2><div class="jh-grid"><?php foreach($ban as $b):?><article class="jh-card"><h3><?=e($b['ten_gian_hang'])?></h3><p><?=e($b['ho_ten'])?></p><p><?=e($b['gioi_thieu'])?></p><?php foreach(['duyet'=>'Duyệt','tu_choi'=>'Từ chối'] as $v=>$ten):?><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=(int)$b['nguoi_dung_id']?>"><input type="hidden" name="loai" value="nguoi_ban"><input type="hidden" name="hanh_dong" value="<?=e($v)?>"><button type="submit"><?=e($ten)?></button></form><?php endforeach;?></article><?php endforeach;?></div><h2>Tin đăng chờ kiểm duyệt</h2><div class="jh-grid"><?php foreach($tin as $t):?><article class="jh-card"><h3><?=e($t['ten'])?></h3><p>Người đăng: <?=e($t['ho_ten'])?> · <?=e(vnd((int)$t['gia']))?></p><p><a href="chung-thu.php?id=<?=(int)$t['id']?>">Kiểm tra chứng thư và ảnh</a></p><?php foreach(['duyet'=>'Duyệt hồ sơ','tu_choi'=>'Yêu cầu bổ sung'] as $v=>$ten):?><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=(int)$t['id']?>"><input type="hidden" name="loai" value="tin_dang"><input type="hidden" name="hanh_dong" value="<?=e($v)?>"><button type="submit"><?=e($ten)?></button></form><?php endforeach;?></article><?php endforeach;?></div></main><?php require dirname(__DIR__, 2).'/inc/footer.php';?>
